{
  "schema_version": "2.0",
  "checklist_id": "FC-CRISPR-AGING-IMMUNE-001",
  "record_id": "local-draft-no-record-yet",
  "hypotheses": [
    {
      "hypothesis_id": "H1",
      "candidate_status": "candidate",
      "assumptions": [
        "The base editor edits the intended locus as designed and intended-locus editing is measurable per animal.",
        "Randomization, blinding, and the prespecified analysis are executed as planned.",
        "The functional immune readout is validated for aged mice in this strain and assay version."
      ],
      "boundary_conditions": [
        "Single strain, sex, and age band; single site; fixed treatment window and dose."
      ],
      "falsifier": {
        "prediction_id": "P1",
        "conditions": "Randomization, blinding, and editing confirmation pass and uncertainty is small enough to separate the arms.",
        "observable": "Prespecified primary functional readout by arm, plus per-animal intended-locus editing fraction.",
        "incompatible_result": "Editor+intended-guide and editor+non-targeting-guide arms are indistinguishable despite confirmed intended-locus editing, or the readout changes without coupling to intended-locus editing.",
        "assumption_failure_checks": [
          "Verify intended-locus editing fraction, off-target burden, blinding integrity, and inter-arm mortality balance before interpreting incompatibility."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT1",
          "rival_hypothesis_id": "H3",
          "focal_expected": "Non-targeting-guide remains vehicle-like; improvement appears late and scales with intended-locus editing fraction.",
          "rival_expected": "Non-targeting-guide improves like intended-guide with early transient cytokine shifts.",
          "indeterminate_result": "Both an early non-targeting-guide effect and a persistent intended-guide-specific component occur - mixed mechanisms."
        },
        {
          "test_id": "DT2",
          "rival_hypothesis_id": "H4",
          "focal_expected": "Restoration replicates under blinding, randomization, and prespecified analysis.",
          "rival_expected": "The exploratory restoration shrinks toward null or fails to replicate.",
          "indeterminate_result": "Direction replicates but magnitude falls below the prespecified threshold - exploratory until powered."
        },
        {
          "test_id": "DT3",
          "rival_hypothesis_id": "H2",
          "focal_expected": "Phenotype couples monotonically to intended-locus editing fraction with low off-target burden.",
          "rival_expected": "Phenotype tracks off-target burden at immune-relevant loci instead.",
          "indeterminate_result": "Intended and off-target fractions collinear, or off-target assay sensitivity too low."
        }
      ],
      "nulls": [
        {
          "null_id": "N1",
          "statement": "The prespecified primary functional readout does not differ between editor+intended-guide and editor+non-targeting-guide arms at the prespecified horizon.",
          "analysis_id": "A1",
          "interpretation_limit": "Failure to reject is not equivalence, absence of effect, or proof of any rival."
        }
      ],
      "controls": [
        {
          "control_id": "NC1",
          "control_type": "negative_outcome",
          "rationale": "The editor+non-targeting-guide arm shares every delivery, Cas9, and guide-RNA pathway but cannot operate through the intended edit.",
          "expected_result": "No improvement beyond vehicle on the prespecified readout.",
          "failure_implication": "The phenotype is delivery/editor/guide-driven or an artifact; the intended-edit mechanism is not supported."
        },
        {
          "control_id": "NC2",
          "control_type": "negative_outcome",
          "rationale": "The vehicle-only arm separates editor exposure from delivery alone and anchors the aged baseline.",
          "expected_result": "Reflects the aged baseline trajectory over the same window.",
          "failure_implication": "Investigate handling, housing, or mortality asymmetries before any causal interpretation."
        },
        {
          "control_id": "PC1",
          "control_type": "positive_control",
          "rationale": "A young untreated reference cohort anchors the youthful immune phenotype the assay must be able to detect.",
          "expected_result": "Young reference separates from aged baseline on the prespecified readout.",
          "failure_implication": "The assay cannot detect restoration; no arm comparison is interpretable until assay sensitivity is restored."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Intended-guide separates from both vehicle and non-targeting-guide, improvement scales with intended-locus editing fraction, off-target burden low, controls pass.",
        "challenges_candidate": "Intended-guide and non-targeting-guide are indistinguishable despite confirmed editing and passing controls.",
        "supports_neither_or_mixed": "Transient non-targeting-guide effect plus persistent intended-guide component, replication direction without magnitude, or a control fails."
      },
      "human_review_status": "pending"
    },
    {
      "hypothesis_id": "H3",
      "candidate_status": "candidate",
      "assumptions": [
        "Delivery vehicle, Cas9, and guide RNA reach immune compartments in all editor-containing arms alike.",
        "Innate sensing of vector or RNA components can remodel immune compartments on the study timescale."
      ],
      "boundary_conditions": [
        "Same editor batch and dose across editor-containing arms; fixed sampling schedule with an early window."
      ],
      "falsifier": {
        "prediction_id": "P2",
        "conditions": "Early and late sampling executed; cytokine panel valid; uncertainty small enough to compare arms.",
        "observable": "Functional readout and innate cytokine panel across non-targeting-guide, vehicle, and intended-guide arms over time.",
        "incompatible_result": "Non-targeting-guide remains vehicle-like while intended-guide improves late.",
        "assumption_failure_checks": [
          "Verify non-targeting-guide arm received the same editor exposure and that early sampling captured the innate window."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT4",
          "rival_hypothesis_id": "H1",
          "focal_expected": "Non-targeting-guide mirrors intended-guide improvement with early transient cytokine shifts.",
          "rival_expected": "Non-targeting-guide vehicle-like; improvement late and coupled to intended-locus editing fraction.",
          "indeterminate_result": "Both patterns present - delivery perturbation and edit-specific restoration coexist."
        }
      ],
      "nulls": [
        {
          "null_id": "N3",
          "statement": "Editor+non-targeting-guide does not differ from vehicle on the prespecified readout at the prespecified horizon.",
          "analysis_id": "A1",
          "interpretation_limit": "Failure to reject is not proof the delivery is immunologically inert - power limits apply."
        }
      ],
      "controls": [
        {
          "control_id": "NC1",
          "control_type": "negative_outcome",
          "rationale": "The non-targeting-guide arm is the direct carrier of every shared delivery, Cas9, and guide pathway for this rival.",
          "expected_result": "Under H3, this arm carries the improvement; under H1 it does not.",
          "failure_implication": "A vehicle-like non-targeting-guide arm challenges the delivery rival."
        },
        {
          "control_id": "PC1",
          "control_type": "positive_control",
          "rationale": "Young reference anchors assay sensitivity so a null NTC arm is not an insensitive assay.",
          "expected_result": "Young reference separates from aged baseline.",
          "failure_implication": "No arm comparison interpretable until assay sensitivity restored."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Non-targeting-guide improvement mirrors intended-guide with early cytokine shifts and transient kinetics.",
        "challenges_candidate": "Non-targeting-guide vehicle-like while intended-guide improves late and coupling holds.",
        "supports_neither_or_mixed": "Both early shared and late edit-specific components occur."
      },
      "human_review_status": "pending"
    },
    {
      "hypothesis_id": "H4",
      "candidate_status": "candidate",
      "assumptions": [
        "The exploratory result involved small n, unblinded assessment, or post hoc readout selection, as unreported details leave open.",
        "Cage, batch, and mortality asymmetries can distort immune phenotypes in aged cohorts."
      ],
      "boundary_conditions": [
        "Replication matches strain, sex, age band, editor, dose, and readout of the exploratory study."
      ],
      "falsifier": {
        "prediction_id": "P4",
        "conditions": "Blinded, randomized, adequately powered replication completes with prespecified analysis.",
        "observable": "Replication effect estimate on the prespecified readout vs the exploratory estimate.",
        "incompatible_result": "Replication reproduces the restoration with intended-guide separated from non-targeting-guide at the prespecified magnitude.",
        "assumption_failure_checks": [
          "Verify power, blinding integrity, cage balance, and mortality symmetry before interpreting replication failure as artifact support."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT5",
          "rival_hypothesis_id": "H1",
          "focal_expected": "Restoration vanishes or shrinks toward null under prespecification and blinding.",
          "rival_expected": "Restoration replicates at prespecified magnitude with the crucial arm contrast.",
          "indeterminate_result": "Direction without magnitude - underpowered replication cannot separate artifact from smaller true effect."
        }
      ],
      "nulls": [
        {
          "null_id": "N4",
          "statement": "Editor+intended-guide does not differ from vehicle on the prespecified readout in the replication cohort.",
          "analysis_id": "A1",
          "interpretation_limit": "Failure to reject is compatible with both artifact and a true-but-smaller effect; it is not proof of artifact."
        }
      ],
      "controls": [
        {
          "control_id": "NC1",
          "control_type": "negative_outcome",
          "rationale": "A non-targeting-guide arm shares every bias pathway of the exploratory design but cannot act through the intended edit.",
          "expected_result": "Under H4, exploratory scoring practices could have produced apparent restoration in any editor-bearing arm.",
          "failure_implication": "A clean, powered replication challenges the artifact rival."
        },
        {
          "control_id": "NC2",
          "control_type": "negative_outcome",
          "rationale": "Vehicle arm anchors the aged baseline and exposes housing or handling asymmetries.",
          "expected_result": "Aged baseline trajectory reproduced across cages.",
          "failure_implication": "Cage or handling asymmetry detected - artifact rival remains live regardless of arm contrasts."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Blinded prespecified replication yields null or sharply shrunk effect; per-arm differences track cage or assessment structure.",
        "challenges_candidate": "Powered blinded replication reproduces restoration with the intended-guide contrast intact.",
        "supports_neither_or_mixed": "Direction without magnitude, or replication blocked by control failure."
      },
      "human_review_status": "pending"
    }
  ]
}
